#include "KS/SRC/global.h"

class beam;
class beam_effect_type;

class beam_effect
{
private:
  beam *my_beam;
  beam_effect_type *effect;
  unsigned short id;
  char mode;
  rational_t timer;
  rational_t loop_delay;
  rational_t duration;

  virtual void dump();
  virtual void set_active();
  virtual void set_delaying();

public:
  beam_effect(beam *);
  virtual ~beam_effect();
  virtual void set_color_delta(const color32&, const color32&, rational_t, rational_t, rational_t, bool);
  virtual void set_width_delta(rational_t, rational_t, rational_t, rational_t, rational_t, bool);
  virtual void set_alpha_delta(uint8, uint8, rational_t, rational_t, rational_t, bool);
  virtual void frame_advance(time_value_t);
  virtual void kill(bool);
  virtual bool is_dead() const;
  virtual bool is_alive() const;
  virtual bool is_delaying() const;
  virtual bool is_active() const;
  virtual bool is_looping() const;
  virtual bool is_inverted() const;
  virtual unsigned short get_id() const;
  virtual void set_id(unsigned short);
  virtual beam_effect *make_instance(beam *);
  virtual void read_width_chunk(chunk_file&);
  virtual void read_alpha_chunk(chunk_file&);
  virtual void read_color_chunk(chunk_file&);
  virtual bool handle_enx_chunk(chunk_file&, stringx&);
};

bool beam_effect::handle_enx_chunk( chunk_file& fs, stringx& label )
{
  if(label == "alpha:")
    read_alpha_chunk(fs);
  else if(label == "width:")
    read_width_chunk(fs);
  else if(label == "color:")
    read_color_chunk(fs);
  else
    error( fs.get_filename() + ": unknown beam_effect type '" + label + "'" );

  return(true);
}
